INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DIN 66261 nur für Softwareentwicklung relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Prozessdarstellung"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt DIN 66261?', 3, '[{"text": "Strukturierte Programmflüsse darstellen", "correct": true, "because": "Nassi-Shneiderman"}, {"text": "Datenbanken modellieren", "correct": false, "because": "Anderer Fokus"}, {"text": "Hardware dokumentieren", "correct": false, "because": "Softwareorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen definiert DIN 66261?', 5, '[{"text": "Sequenz", "correct": true, "because": "Lineare Abfolge"}, {"text": "Auswahl", "correct": true, "because": "Entscheidungen"}, {"text": "Schleifen", "correct": true, "because": "Wiederholungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIN 66261 nutzt Struktogramme. b) Es ist für objektorientierte Programmierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Imperative Struktur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei DIN 66261?', 4, '[{"text": "Programmfluss", "correct": false, "because": "Kern der Norm"}, {"text": "Strukturierung", "correct": false, "because": "Grundprinzip"}, {"text": "Farben", "correct": true, "because": "Nicht genormt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DIN 66261 Schleifen darstellt?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederholungen möglich"}, {"text": "Nein", "correct": false, "because": "Teil der Struktogramme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol zeigt eine Entscheidung in DIN 66261?', 3, '[{"text": "Dreieck im Rechteck", "correct": true, "because": "Auswahl darstellen"}, {"text": "Kreis", "correct": false, "because": "Nicht genormt"}, {"text": "Quadrat", "correct": false, "because": "Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DIN 66261?', 5, '[{"text": "Klarheit", "correct": true, "because": "Übersichtliche Struktur"}, {"text": "Eindeutigkeit", "correct": true, "because": "Normierte Darstellung"}, {"text": "Schnelle Codierung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DIN 66261 ist für Struktogramme. b) Es nutzt nur Pfeile. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Pfeile nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DIN 66261?', 4, '[{"text": "Rechteckige Blöcke", "correct": false, "because": "Grundelement"}, {"text": "Strukturierte Logik", "correct": false, "because": "Kernprinzip"}, {"text": "3D-Grafiken", "correct": true, "because": "2D-Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DIN 66261 für objektorientierte Programmierung geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Imperative Struktur"}, {"text": "Ja", "correct": false, "because": "Nicht OOP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmstrukturen zeigt DIN 66261?', 4, '[{"text": "Verzweigungen", "correct": true, "because": "Entscheidungen"}, {"text": "Schleifen", "correct": true, "because": "Wiederholungen"}, {"text": "Klassen", "correct": false, "because": "Nicht OOP"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DIN 66261 veraltet ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger genutzt"}, {"text": "Nein", "correct": false, "because": "Noch bekannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DIN 66261?', 3, '[{"text": "Übersichtlichkeit", "correct": true, "because": "Klare Darstellung"}, {"text": "Farben", "correct": false, "because": "Nicht genormt"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIN 66261 ist für strukturierte Programmierung. b) Es nutzt UML.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "UML ist anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nutzen hat DIN 66261?', 5, '[{"text": "Einheitliche Darstellung", "correct": true, "because": "Normierte Strukturen"}, {"text": "Lesbarkeit", "correct": true, "because": "Klar strukturiert"}, {"text": "Datenmodellierung", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DIN 66261 unwichtig?', 3, '[{"text": "Blöcke", "correct": false, "because": "Kern der Darstellung"}, {"text": "Logische Abfolge", "correct": false, "because": "Grundprinzip"}, {"text": "Schriftart", "correct": true, "because": "Nicht normiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt DIN 66261 Pfeile wie Flussdiagramme?', 3, '[{"text": "Nein", "correct": true, "because": "Blockstruktur"}, {"text": "Ja", "correct": false, "because": "Keine Pfeile nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DIN 66261 für Anfänger geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Einfach verständlich"}, {"text": "Nein", "correct": false, "because": "Lernbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist in DIN 66261 zentral?', 4, '[{"text": "Rechteckige Blöcke", "correct": true, "because": "Strukturierte Darstellung"}, {"text": "Pfeile", "correct": false, "because": "Nicht genutzt"}, {"text": "Klassenmodelle", "correct": false, "because": "Nicht OOP"}]');
